#define sfract(x)      min( fract(x)/(1.-fwidth(x)), fract(-(x))/fwidth(x) ) // or 1.5*fwidth
#define smod(x,n)     (sfract((x)/(n))*(n))
#define sfloor(x)      max( floor(x), x - sfract(x) )

//  ---  variant: tunable smooth cliff 
#define sfractN(x,w)   min( fract(x)/(1.-(w)), fract(-x)/(w) )
#define smodN(x,n,w)  (sfractN((x)/(n),w)*(n))
#define sfloorN(x,w)   max( floor(x), x - sfractN(x,w) )


void mainImage( out vec4 O, vec2 u )
{
    vec2 R = iResolution.xy, V,
         U = 10.* (u/R - .5);

    float y = floor(U.y), x = U.x,                                            // show funcs ( white )
          v =  y == -2. ? fract( x )
             : y == 0. ? sfract( x )
             : y == 2. ? sfractN( x, .05 )
             : 0.;
    O = U.x > 0. 
          ? vec4( fract(U.y) < v )
          : vec4( smoothstep(0., 1.5*fwidth(v), v - fract(U.y) ) );
       // : vec4( smoothstep( 1.5*fwidth(v), 0., abs(v - fract(U.y) )) );

    v = sfloorN( x, .1 );                                                     // --- show sfloor (red )
    O.r += smoothstep( 1.5*max(fwidth(U.y),fwidth(v)), 0., abs(v - U.y ) ); 

    V = (10.*(u-.5*R)/R.y) * mat2(cos( .3*iTime+vec4(0,11,33,0)));            // --- exemple ( green )
    V = sfract( V );
    if (y<-2. && U.x>0.) O.g = V.x * V.y;
}
